-- 리눅스 세트 338. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_linux_archive_backup_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 338, '아카이브와 간단한 백업 직접 해 보기: tar czf·tzf·xzf, --exclude, gzip -k, cp -a, sha256sum, 날짜 이름, 오래된 백업 정리', '작은 폴더로 백업의 한 사이클을 직접 해 봅니다. tar 로 묶고 목록을 보고 원하는 폴더에 풀고, --exclude 로 뺄 것을 정하고, gzip -k 와 zcat 으로 압축 파일을 다루고, cp -a 로 권한과 시각을 보존하며, sha256sum 으로 복사본을 검증하고, date 로 이름을 붙이고, 오래된 백업을 정리합니다. 채점은 아카이브의 내용을 직접 열어 봅니다.', 'linux', '리눅스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 338);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 338, 1, '디렉토리를 tar.gz 로 묶고 압축하기 (czf, -C)', '`/tmp/lab/project` 폴더를 **`/tmp/backup.tar.gz`** 로 묶고 압축하세요. 아카이브 안의 경로는 **`project/...`** 로 시작해야 하고, `tmp/lab/` 같은 앞 경로가 붙으면 안 됩니다.', '`tar czf 아카이브 대상` 에서 c 는 만들기, z 는 gzip 압축, f 는 파일 이름입니다. 앞 경로를 떼려면 `-C 디렉토리` 로 먼저 그 위치로 옮겨 간 다음 상대 경로로 대상을 적습니다.', 'tar czf /tmp/backup.tar.gz -C /tmp/lab project
tar tzf /tmp/backup.tar.gz

# -C /tmp/lab 으로 이동한 뒤 project 를 묶었기 때문에 안의 경로가 project/... 로 시작한다', '["sh", "-c", "rm -rf /tmp/lab /tmp/restore /tmp/*.txt /tmp/*.gz /tmp/*.tgz\\nmkdir -p /tmp/lab/project/bin /tmp/lab/project/logs /tmp/lab/data /tmp/lab/backups /tmp/lab/daily /tmp/lab/src /tmp/lab/.mk/site\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > /tmp/lab/project/app.conf\\nprintf ''remember to rotate\\\\n'' > /tmp/lab/project/notes.txt\\nprintf ''#!/bin/sh\\\\necho run\\\\n'' > /tmp/lab/project/bin/run.sh\\nchmod 755 /tmp/lab/project/bin/run.sh\\nprintf ''start\\\\nwarn\\\\n'' > /tmp/lab/project/logs/app.log\\nprintf ''old line\\\\n'' > /tmp/lab/project/logs/old.log\\nprintf ''hello site\\\\n'' > /tmp/lab/.mk/site/index.html\\nprintf ''body{}\\\\n'' > /tmp/lab/.mk/site/style.css\\ntar czf /tmp/lab/site.tar.gz -C /tmp/lab/.mk site\\nrm -rf /tmp/lab/.mk\\nprintf ''a1\\\\n'' > /tmp/lab/data/a.txt\\nprintf ''b1\\\\n'' > /tmp/lab/data/b.txt\\nprintf ''id,qty\\\\n1,10\\\\n2,20\\\\n'' > /tmp/lab/data/report.csv\\nseq 1 200 > /tmp/lab/big.txt\\nprintf ''INFO start\\\\nERROR disk\\\\nINFO ok\\\\nERROR net\\\\nERROR db\\\\n'' | gzip -n > /tmp/lab/server.log.gz\\nprintf ''echo conf\\\\n'' > /tmp/lab/src/conf.sh\\nchmod 750 /tmp/lab/src/conf.sh\\ntouch -d ''2020-01-01 00:00:00'' /tmp/lab/src/conf.sh\\nfor d in 01 02 03 04 05; do : > /tmp/lab/daily/data-2026-01-$d.tar.gz; touch -d \\"2026-01-$d 00:00:00\\" /tmp/lab/daily/data-2026-01-$d.tar.gz; done\\ntrue"]', '["sh", "-c", "( gzip -t /tmp/backup.tar.gz ) && ( tar tzf /tmp/backup.tar.gz | grep -qx \\"project/app.conf\\" ) && ( ! tar tzf /tmp/backup.tar.gz | grep -q \\"^tmp/\\" ) && ( tar xzOf /tmp/backup.tar.gz project/app.conf | grep -qx \\"port=8080\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "백업 파일이 올바른 gzip 이다", "cmd": ["sh", "-c", "gzip -t /tmp/backup.tar.gz"]}, {"label": "project/app.conf 가 들어 있다", "cmd": ["sh", "-c", "tar tzf /tmp/backup.tar.gz | grep -qx \\"project/app.conf\\""]}, {"label": "앞 경로(tmp/) 가 붙어 있지 않다", "cmd": ["sh", "-c", "! tar tzf /tmp/backup.tar.gz | grep -q \\"^tmp/\\""]}, {"label": "app.conf 내용이 그대로 들어 있다", "cmd": ["sh", "-c", "tar xzOf /tmp/backup.tar.gz project/app.conf | grep -qx \\"port=8080\\""]}]', '[{"title": "GNU tar 매뉴얼", "url": "https://www.gnu.org/software/tar/manual/"}, {"title": "GNU tar 매뉴얼: 파일 제외하기 (--exclude)", "url": "https://www.gnu.org/software/tar/manual/html_section/exclude.html"}, {"title": "GNU coreutils 매뉴얼: cp 사용법 (-a)", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cp-invocation.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 338 AND order_index = 1);

