SELECT 338, 2, '아카이브 안을 풀지 않고 목록만 보기 (tzf)', '`/tmp/lab/site.tar.gz` 가 있습니다. 파일을 **풀지 않고** 안에 무엇이 들어 있는지 나열해서, 그 목록을 **`/tmp/list.txt`** 에 저장하세요. (이름만 한 줄씩, 자세히 보기 옵션은 쓰지 않습니다.)', '`tar` 의 t 는 목록(list) 보기입니다. 압축 파일이면 z 와 f 를 함께 쓰고, 출력은 `>` 로 파일에 보냅니다.', 'tar tzf /tmp/lab/site.tar.gz > /tmp/list.txt
cat /tmp/list.txt

# t 는 아무것도 풀지 않고 목록만 보여 준다', '["sh", "-c", "rm -rf /tmp/lab /tmp/restore /tmp/*.txt /tmp/*.gz /tmp/*.tgz\\nmkdir -p /tmp/lab/project/bin /tmp/lab/project/logs /tmp/lab/data /tmp/lab/backups /tmp/lab/daily /tmp/lab/src /tmp/lab/.mk/site\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > /tmp/lab/project/app.conf\\nprintf ''remember to rotate\\\\n'' > /tmp/lab/project/notes.txt\\nprintf ''#!/bin/sh\\\\necho run\\\\n'' > /tmp/lab/project/bin/run.sh\\nchmod 755 /tmp/lab/project/bin/run.sh\\nprintf ''start\\\\nwarn\\\\n'' > /tmp/lab/project/logs/app.log\\nprintf ''old line\\\\n'' > /tmp/lab/project/logs/old.log\\nprintf ''hello site\\\\n'' > /tmp/lab/.mk/site/index.html\\nprintf ''body{}\\\\n'' > /tmp/lab/.mk/site/style.css\\ntar czf /tmp/lab/site.tar.gz -C /tmp/lab/.mk site\\nrm -rf /tmp/lab/.mk\\nprintf ''a1\\\\n'' > /tmp/lab/data/a.txt\\nprintf ''b1\\\\n'' > /tmp/lab/data/b.txt\\nprintf ''id,qty\\\\n1,10\\\\n2,20\\\\n'' > /tmp/lab/data/report.csv\\nseq 1 200 > /tmp/lab/big.txt\\nprintf ''INFO start\\\\nERROR disk\\\\nINFO ok\\\\nERROR net\\\\nERROR db\\\\n'' | gzip -n > /tmp/lab/server.log.gz\\nprintf ''echo conf\\\\n'' > /tmp/lab/src/conf.sh\\nchmod 750 /tmp/lab/src/conf.sh\\ntouch -d ''2020-01-01 00:00:00'' /tmp/lab/src/conf.sh\\nfor d in 01 02 03 04 05; do : > /tmp/lab/daily/data-2026-01-$d.tar.gz; touch -d \\"2026-01-$d 00:00:00\\" /tmp/lab/daily/data-2026-01-$d.tar.gz; done\\ntrue"]', '["sh", "-c", "( tar tzf /tmp/lab/site.tar.gz | cmp -s - /tmp/list.txt ) && ( grep -qx \\"site/index.html\\" /tmp/list.txt ) && ( [ ! -e /tmp/lab/site ] && [ ! -e /site ] && [ ! -e /index.html ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "/tmp/list.txt 가 tzf 목록과 같다", "cmd": ["sh", "-c", "tar tzf /tmp/lab/site.tar.gz | cmp -s - /tmp/list.txt"]}, {"label": "목록에 site/index.html 이 있다", "cmd": ["sh", "-c", "grep -qx \\"site/index.html\\" /tmp/list.txt"]}, {"label": "아카이브를 풀지 않았다", "cmd": ["sh", "-c", "[ ! -e /tmp/lab/site ] && [ ! -e /site ] && [ ! -e /index.html ]"]}]', '[{"title": "GNU tar 매뉴얼", "url": "https://www.gnu.org/software/tar/manual/"}, {"title": "GNU tar 매뉴얼: 파일 제외하기 (--exclude)", "url": "https://www.gnu.org/software/tar/manual/html_section/exclude.html"}, {"title": "GNU coreutils 매뉴얼: cp 사용법 (-a)", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cp-invocation.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 338 AND order_index = 2);

