SELECT 338, 3, '원하는 폴더에 풀기 (xzf -C)', '`/tmp/lab/site.tar.gz` 를 **`/tmp/restore`** 폴더에 풀어서 `/tmp/restore/site/index.html` 이 생기게 하세요. 풀 폴더는 아직 없습니다. 현재 위치(`/tmp/lab` 등)에는 `site` 가 생기면 안 됩니다.', '`tar xzf 아카이브 -C 풀폴더` 입니다. `-C` 로 지정하는 폴더는 **미리 있어야** 하니, 먼저 만드세요 (`mkdir -p`).', 'mkdir -p /tmp/restore
tar xzf /tmp/lab/site.tar.gz -C /tmp/restore
cat /tmp/restore/site/index.html

# -C 폴더가 없으면 tar 가 오류를 낸다. 먼저 mkdir -p 로 만든다', '["sh", "-c", "rm -rf /tmp/lab /tmp/restore /tmp/*.txt /tmp/*.gz /tmp/*.tgz\\nmkdir -p /tmp/lab/project/bin /tmp/lab/project/logs /tmp/lab/data /tmp/lab/backups /tmp/lab/daily /tmp/lab/src /tmp/lab/.mk/site\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > /tmp/lab/project/app.conf\\nprintf ''remember to rotate\\\\n'' > /tmp/lab/project/notes.txt\\nprintf ''#!/bin/sh\\\\necho run\\\\n'' > /tmp/lab/project/bin/run.sh\\nchmod 755 /tmp/lab/project/bin/run.sh\\nprintf ''start\\\\nwarn\\\\n'' > /tmp/lab/project/logs/app.log\\nprintf ''old line\\\\n'' > /tmp/lab/project/logs/old.log\\nprintf ''hello site\\\\n'' > /tmp/lab/.mk/site/index.html\\nprintf ''body{}\\\\n'' > /tmp/lab/.mk/site/style.css\\ntar czf /tmp/lab/site.tar.gz -C /tmp/lab/.mk site\\nrm -rf /tmp/lab/.mk\\nprintf ''a1\\\\n'' > /tmp/lab/data/a.txt\\nprintf ''b1\\\\n'' > /tmp/lab/data/b.txt\\nprintf ''id,qty\\\\n1,10\\\\n2,20\\\\n'' > /tmp/lab/data/report.csv\\nseq 1 200 > /tmp/lab/big.txt\\nprintf ''INFO start\\\\nERROR disk\\\\nINFO ok\\\\nERROR net\\\\nERROR db\\\\n'' | gzip -n > /tmp/lab/server.log.gz\\nprintf ''echo conf\\\\n'' > /tmp/lab/src/conf.sh\\nchmod 750 /tmp/lab/src/conf.sh\\ntouch -d ''2020-01-01 00:00:00'' /tmp/lab/src/conf.sh\\nfor d in 01 02 03 04 05; do : > /tmp/lab/daily/data-2026-01-$d.tar.gz; touch -d \\"2026-01-$d 00:00:00\\" /tmp/lab/daily/data-2026-01-$d.tar.gz; done\\ntrue"]', '["sh", "-c", "( grep -qx \\"hello site\\" /tmp/restore/site/index.html ) && ( grep -qx \\"body{}\\" /tmp/restore/site/style.css ) && ( [ ! -e /tmp/lab/site ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "index.html 내용이 복원되었다", "cmd": ["sh", "-c", "grep -qx \\"hello site\\" /tmp/restore/site/index.html"]}, {"label": "style.css 도 복원되었다", "cmd": ["sh", "-c", "grep -qx \\"body{}\\" /tmp/restore/site/style.css"]}, {"label": "현재 위치에는 풀지 않았다", "cmd": ["sh", "-c", "[ ! -e /tmp/lab/site ]"]}]', '[{"title": "GNU tar 매뉴얼", "url": "https://www.gnu.org/software/tar/manual/"}, {"title": "GNU tar 매뉴얼: 파일 제외하기 (--exclude)", "url": "https://www.gnu.org/software/tar/manual/html_section/exclude.html"}, {"title": "GNU coreutils 매뉴얼: cp 사용법 (-a)", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cp-invocation.html"}]'
