INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 338, 4, '특정 폴더는 빼고 묶기 (--exclude)', '`/tmp/lab/project` 를 **`/tmp/clean.tar.gz`** 로 묶되, **`logs` 폴더는 빼세요.** 아카이브 안 경로는 `project/...` 로 시작합니다. 나머지 파일(`app.conf`, `notes.txt`, `bin/run.sh`)은 들어 있어야 합니다.', '`--exclude=패턴` 으로 뺄 이름을 지정합니다. 이 옵션은 묶을 대상(`project`)보다 **앞**에 적는 것이 안전합니다. 만든 뒤 `tar tzf` 로 빠졌는지 확인해 보세요.', 'tar czf /tmp/clean.tar.gz --exclude=logs -C /tmp/lab project
tar tzf /tmp/clean.tar.gz

# --exclude 는 묶을 대상보다 앞에 둔다', '["sh", "-c", "rm -rf /tmp/lab /tmp/restore /tmp/*.txt /tmp/*.gz /tmp/*.tgz\\nmkdir -p /tmp/lab/project/bin /tmp/lab/project/logs /tmp/lab/data /tmp/lab/backups /tmp/lab/daily /tmp/lab/src /tmp/lab/.mk/site\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > /tmp/lab/project/app.conf\\nprintf ''remember to rotate\\\\n'' > /tmp/lab/project/notes.txt\\nprintf ''#!/bin/sh\\\\necho run\\\\n'' > /tmp/lab/project/bin/run.sh\\nchmod 755 /tmp/lab/project/bin/run.sh\\nprintf ''start\\\\nwarn\\\\n'' > /tmp/lab/project/logs/app.log\\nprintf ''old line\\\\n'' > /tmp/lab/project/logs/old.log\\nprintf ''hello site\\\\n'' > /tmp/lab/.mk/site/index.html\\nprintf ''body{}\\\\n'' > /tmp/lab/.mk/site/style.css\\ntar czf /tmp/lab/site.tar.gz -C /tmp/lab/.mk site\\nrm -rf /tmp/lab/.mk\\nprintf ''a1\\\\n'' > /tmp/lab/data/a.txt\\nprintf ''b1\\\\n'' > /tmp/lab/data/b.txt\\nprintf ''id,qty\\\\n1,10\\\\n2,20\\\\n'' > /tmp/lab/data/report.csv\\nseq 1 200 > /tmp/lab/big.txt\\nprintf ''INFO start\\\\nERROR disk\\\\nINFO ok\\\\nERROR net\\\\nERROR db\\\\n'' | gzip -n > /tmp/lab/server.log.gz\\nprintf ''echo conf\\\\n'' > /tmp/lab/src/conf.sh\\nchmod 750 /tmp/lab/src/conf.sh\\ntouch -d ''2020-01-01 00:00:00'' /tmp/lab/src/conf.sh\\nfor d in 01 02 03 04 05; do : > /tmp/lab/daily/data-2026-01-$d.tar.gz; touch -d \\"2026-01-$d 00:00:00\\" /tmp/lab/daily/data-2026-01-$d.tar.gz; done\\ntrue"]', '["sh", "-c", "( gzip -t /tmp/clean.tar.gz ) && ( l=$(tar tzf /tmp/clean.tar.gz); echo \\"$l\\" | grep -qx \\"project/app.conf\\" && echo \\"$l\\" | grep -qx \\"project/notes.txt\\" && echo \\"$l\\" | grep -qx \\"project/bin/run.sh\\" ) && ( ! tar tzf /tmp/clean.tar.gz | grep -q \\"logs\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "올바른 gzip 이다", "cmd": ["sh", "-c", "gzip -t /tmp/clean.tar.gz"]}, {"label": "app.conf, notes.txt, run.sh 가 들어 있다", "cmd": ["sh", "-c", "l=$(tar tzf /tmp/clean.tar.gz); echo \\"$l\\" | grep -qx \\"project/app.conf\\" && echo \\"$l\\" | grep -qx \\"project/notes.txt\\" && echo \\"$l\\" | grep -qx \\"project/bin/run.sh\\""]}, {"label": "logs 는 들어 있지 않다", "cmd": ["sh", "-c", "! tar tzf /tmp/clean.tar.gz | grep -q \\"logs\\""]}]', '[{"title": "GNU tar 매뉴얼", "url": "https://www.gnu.org/software/tar/manual/"}, {"title": "GNU tar 매뉴얼: 파일 제외하기 (--exclude)", "url": "https://www.gnu.org/software/tar/manual/html_section/exclude.html"}, {"title": "GNU coreutils 매뉴얼: cp 사용법 (-a)", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cp-invocation.html"}]'
