INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 338, 5, 'tar 가 "Removing leading `/`" 라고 알릴 때', '`tar czf /tmp/x.tar.gz /tmp/lab/project` 처럼 **절대 경로**로 묶으면 아래와 같은 메시지가 나옵니다. 이 메시지의 뜻으로 알맞은 것을 고르세요.

```
tar: Removing leading `/'' from member names
```', '오류가 아니라 안내입니다. 아카이브를 **풀 때** 어떤 일이 생길 수 있는지 생각해 보세요. 절대 경로가 그대로 저장되어 있다면 풀 때 어디가 덮어씌워질까요?', NULL, NULL, '[]', 'choice', '["권한이 없어 일부 파일이 읽히지 않아 아카이브에서 빠졌다는 경고이며, 빠진 파일은 직접 다시 묶어야 한다", "파일이 너무 커서 일부만 압축했다는 뜻이며, 나머지 내용은 다음 실행에서 이어서 묶인다", "아카이브에 저장되는 경로의 맨 앞 `/` 를 떼어 상대 경로로 만든다는 안내다. 풀 때 시스템의 원래 경로를 덮어쓰지 않게 하려는 것이다", "압축에 실패해서 압축되지 않은 tar 파일만 만들어졌다는 뜻이므로 gzip 으로 다시 압축해야 한다"]', 2, '`Removing leading /` 는 오류가 아니라 **안내**입니다. tar 는 기본으로 멤버 이름 맨 앞의 `/` 를 떼서 `tmp/lab/project/...` 처럼 상대 경로로 저장합니다. 그래야 나중에 풀 때 지금 쓰는 시스템의 `/tmp/lab/project` 를 우연히 덮어쓰지 않고, 풀기 위치(`-C`) 밑에 풀립니다. 파일이 빠졌거나 압축이 실패했다는 뜻이 아니며, 실제로 빠진 파일이 있으면 별도의 오류 메시지가 따로 나옵니다.', NULL, NULL, NULL, '[{"title": "GNU tar 매뉴얼", "url": "https://www.gnu.org/software/tar/manual/"}, {"title": "GNU tar 매뉴얼: 파일 제외하기 (--exclude)", "url": "https://www.gnu.org/software/tar/manual/html_section/exclude.html"}, {"title": "GNU coreutils 매뉴얼: cp 사용법 (-a)", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cp-invocation.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 338 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 338, 6, '원본을 남기고 gzip 으로 압축하기 (gzip -k)', '`/tmp/lab/big.txt` 를 gzip 으로 압축해서 `/tmp/lab/big.txt.gz` 를 만드세요. 단, **원본 `big.txt` 도 그대로 남아 있어야** 합니다.', '`gzip 파일` 은 원본을 지우고 `.gz` 로 바꿔 버립니다. 원본을 **keep** 하는 옵션이 있습니다. 풀 때는 `gunzip` 이 짝입니다.', 'gzip -k /tmp/lab/big.txt
ls -l /tmp/lab/big.txt /tmp/lab/big.txt.gz

# -k (keep) 가 없으면 big.txt 는 사라지고 big.txt.gz 만 남는다', '["sh", "-c", "rm -rf /tmp/lab /tmp/restore /tmp/*.txt /tmp/*.gz /tmp/*.tgz\\nmkdir -p /tmp/lab/project/bin /tmp/lab/project/logs /tmp/lab/data /tmp/lab/backups /tmp/lab/daily /tmp/lab/src /tmp/lab/.mk/site\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > /tmp/lab/project/app.conf\\nprintf ''remember to rotate\\\\n'' > /tmp/lab/project/notes.txt\\nprintf ''#!/bin/sh\\\\necho run\\\\n'' > /tmp/lab/project/bin/run.sh\\nchmod 755 /tmp/lab/project/bin/run.sh\\nprintf ''start\\\\nwarn\\\\n'' > /tmp/lab/project/logs/app.log\\nprintf ''old line\\\\n'' > /tmp/lab/project/logs/old.log\\nprintf ''hello site\\\\n'' > /tmp/lab/.mk/site/index.html\\nprintf ''body{}\\\\n'' > /tmp/lab/.mk/site/style.css\\ntar czf /tmp/lab/site.tar.gz -C /tmp/lab/.mk site\\nrm -rf /tmp/lab/.mk\\nprintf ''a1\\\\n'' > /tmp/lab/data/a.txt\\nprintf ''b1\\\\n'' > /tmp/lab/data/b.txt\\nprintf ''id,qty\\\\n1,10\\\\n2,20\\\\n'' > /tmp/lab/data/report.csv\\nseq 1 200 > /tmp/lab/big.txt\\nprintf ''INFO start\\\\nERROR disk\\\\nINFO ok\\\\nERROR net\\\\nERROR db\\\\n'' | gzip -n > /tmp/lab/server.log.gz\\nprintf ''echo conf\\\\n'' > /tmp/lab/src/conf.sh\\nchmod 750 /tmp/lab/src/conf.sh\\ntouch -d ''2020-01-01 00:00:00'' /tmp/lab/src/conf.sh\\nfor d in 01 02 03 04 05; do : > /tmp/lab/daily/data-2026-01-$d.tar.gz; touch -d \\"2026-01-$d 00:00:00\\" /tmp/lab/daily/data-2026-01-$d.tar.gz; done\\ntrue"]', '["sh", "-c", "( gzip -t /tmp/lab/big.txt.gz ) && ( [ \\"$(wc -l < /tmp/lab/big.txt)\\" -eq 200 ] ) && ( zcat /tmp/lab/big.txt.gz | cmp -s - /tmp/lab/big.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "big.txt.gz 가 올바른 gzip 이다", "cmd": ["sh", "-c", "gzip -t /tmp/lab/big.txt.gz"]}, {"label": "원본 big.txt 가 남아 있다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/big.txt)\\" -eq 200 ]"]}, {"label": "압축 파일을 풀면 원본과 같다", "cmd": ["sh", "-c", "zcat /tmp/lab/big.txt.gz | cmp -s - /tmp/lab/big.txt"]}]', '[{"title": "GNU tar 매뉴얼", "url": "https://www.gnu.org/software/tar/manual/"}, {"title": "GNU tar 매뉴얼: 파일 제외하기 (--exclude)", "url": "https://www.gnu.org/software/tar/manual/html_section/exclude.html"}, {"title": "GNU coreutils 매뉴얼: cp 사용법 (-a)", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cp-invocation.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 338 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 338, 7, '풀지 않고 압축된 로그 바로 읽기', '`/tmp/lab/server.log.gz` 는 압축된 로그입니다. **압축을 파일로 풀지 않고** 내용을 바로 읽어 `ERROR` 가 몇 줄인지 세려고 합니다. 빈칸에 알맞은 명령을 채우세요.', '내용을 표준 출력으로 내보내서 파이프로 넘길 수 있는 명령이어야 합니다. 이름에 "cat" 의 뜻이 들어 있습니다.', NULL, NULL, '[]', 'fill', '["zcat", "gunzip", "cat", "gzip"]', NULL, '`zcat` 은 gzip 파일을 풀어서 **표준 출력**으로 내보내므로 파이프로 이어 쓸 수 있고, 원본 `.gz` 는 그대로 남습니다. `gunzip` 과 `gzip` 은 기본적으로 파일을 풀거나 압축해 **파일을 바꾸고** 파이프로 내용을 내보내지 않습니다. `cat` 은 압축된 바이트를 그대로 보여 주므로 글자를 셀 수 없습니다.', '[0]', '{0} /tmp/lab/server.log.gz | grep -c ERROR', NULL, '[{"title": "GNU tar 매뉴얼", "url": "https://www.gnu.org/software/tar/manual/"}, {"title": "GNU tar 매뉴얼: 파일 제외하기 (--exclude)", "url": "https://www.gnu.org/software/tar/manual/html_section/exclude.html"}, {"title": "GNU coreutils 매뉴얼: cp 사용법 (-a)", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cp-invocation.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 338 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 338, 8, '권한과 수정 시각까지 그대로 복사하기 (cp -a)', '`/tmp/lab/src` 폴더(안의 `conf.sh` 는 권한 `750`, 수정 시각은 2020년)를 **`/tmp/lab/copy`** 로 복사하세요. 복사본의 `conf.sh` 도 **권한(750)과 수정 시각이 원본과 같아야** 합니다.', '`cp -r` 은 폴더를 복사하지만 수정 시각은 "지금" 으로 바뀝니다. 권한·시각·소유자까지 보존하는 **archive** 옵션 한 개가 있습니다. 확인은 `stat -c "%a %y" 파일`.', 'cp -a /tmp/lab/src /tmp/lab/copy
stat -c ''%a %y'' /tmp/lab/src/conf.sh /tmp/lab/copy/conf.sh

# cp -r 로 하면 copy/conf.sh 의 수정 시각이 복사한 순간으로 바뀐다', '["sh", "-c", "rm -rf /tmp/lab /tmp/restore /tmp/*.txt /tmp/*.gz /tmp/*.tgz\\nmkdir -p /tmp/lab/project/bin /tmp/lab/project/logs /tmp/lab/data /tmp/lab/backups /tmp/lab/daily /tmp/lab/src /tmp/lab/.mk/site\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > /tmp/lab/project/app.conf\\nprintf ''remember to rotate\\\\n'' > /tmp/lab/project/notes.txt\\nprintf ''#!/bin/sh\\\\necho run\\\\n'' > /tmp/lab/project/bin/run.sh\\nchmod 755 /tmp/lab/project/bin/run.sh\\nprintf ''start\\\\nwarn\\\\n'' > /tmp/lab/project/logs/app.log\\nprintf ''old line\\\\n'' > /tmp/lab/project/logs/old.log\\nprintf ''hello site\\\\n'' > /tmp/lab/.mk/site/index.html\\nprintf ''body{}\\\\n'' > /tmp/lab/.mk/site/style.css\\ntar czf /tmp/lab/site.tar.gz -C /tmp/lab/.mk site\\nrm -rf /tmp/lab/.mk\\nprintf ''a1\\\\n'' > /tmp/lab/data/a.txt\\nprintf ''b1\\\\n'' > /tmp/lab/data/b.txt\\nprintf ''id,qty\\\\n1,10\\\\n2,20\\\\n'' > /tmp/lab/data/report.csv\\nseq 1 200 > /tmp/lab/big.txt\\nprintf ''INFO start\\\\nERROR disk\\\\nINFO ok\\\\nERROR net\\\\nERROR db\\\\n'' | gzip -n > /tmp/lab/server.log.gz\\nprintf ''echo conf\\\\n'' > /tmp/lab/src/conf.sh\\nchmod 750 /tmp/lab/src/conf.sh\\ntouch -d ''2020-01-01 00:00:00'' /tmp/lab/src/conf.sh\\nfor d in 01 02 03 04 05; do : > /tmp/lab/daily/data-2026-01-$d.tar.gz; touch -d \\"2026-01-$d 00:00:00\\" /tmp/lab/daily/data-2026-01-$d.tar.gz; done\\ntrue"]', '["sh", "-c", "( cmp -s /tmp/lab/src/conf.sh /tmp/lab/copy/conf.sh ) && ( [ \\"$(stat -c %a /tmp/lab/copy/conf.sh)\\" = 750 ] ) && ( [ \\"$(stat -c %Y /tmp/lab/copy/conf.sh)\\" = \\"$(stat -c %Y /tmp/lab/src/conf.sh)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "복사본 conf.sh 가 있고 내용이 같다", "cmd": ["sh", "-c", "cmp -s /tmp/lab/src/conf.sh /tmp/lab/copy/conf.sh"]}, {"label": "권한이 750 으로 유지되었다", "cmd": ["sh", "-c", "[ \\"$(stat -c %a /tmp/lab/copy/conf.sh)\\" = 750 ]"]}, {"label": "수정 시각이 원본과 같다", "cmd": ["sh", "-c", "[ \\"$(stat -c %Y /tmp/lab/copy/conf.sh)\\" = \\"$(stat -c %Y /tmp/lab/src/conf.sh)\\" ]"]}]', '[{"title": "GNU tar 매뉴얼", "url": "https://www.gnu.org/software/tar/manual/"}, {"title": "GNU tar 매뉴얼: 파일 제외하기 (--exclude)", "url": "https://www.gnu.org/software/tar/manual/html_section/exclude.html"}, {"title": "GNU coreutils 매뉴얼: cp 사용법 (-a)", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cp-invocation.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 338 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 338, 9, '복사본이 같은지 체크섬으로 확인하기 (sha256sum)', '`/tmp/lab/data/report.csv` 를 **`/tmp/lab/report.bak`** 으로 복사한 뒤, 원본과 복사본의 **sha256 체크섬을 한 번에** `/tmp/lab/sums.txt` 에 저장하세요. (두 줄, 파일 이름은 **전체 경로**로 적습니다.) 그 파일로 `sha256sum -c` 검사가 통과해야 합니다.', '`sha256sum 파일1 파일2 > 기록파일` 은 파일마다 한 줄씩 해시와 이름을 적습니다. 나중에 `sha256sum -c 기록파일` 로 다시 맞춰 볼 수 있습니다.', 'cp /tmp/lab/data/report.csv /tmp/lab/report.bak
sha256sum /tmp/lab/data/report.csv /tmp/lab/report.bak > /tmp/lab/sums.txt
cat /tmp/lab/sums.txt
sha256sum -c /tmp/lab/sums.txt

# 두 줄의 해시가 같으면 내용이 한 글자도 다르지 않다는 뜻이다', '["sh", "-c", "rm -rf /tmp/lab /tmp/restore /tmp/*.txt /tmp/*.gz /tmp/*.tgz\\nmkdir -p /tmp/lab/project/bin /tmp/lab/project/logs /tmp/lab/data /tmp/lab/backups /tmp/lab/daily /tmp/lab/src /tmp/lab/.mk/site\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > /tmp/lab/project/app.conf\\nprintf ''remember to rotate\\\\n'' > /tmp/lab/project/notes.txt\\nprintf ''#!/bin/sh\\\\necho run\\\\n'' > /tmp/lab/project/bin/run.sh\\nchmod 755 /tmp/lab/project/bin/run.sh\\nprintf ''start\\\\nwarn\\\\n'' > /tmp/lab/project/logs/app.log\\nprintf ''old line\\\\n'' > /tmp/lab/project/logs/old.log\\nprintf ''hello site\\\\n'' > /tmp/lab/.mk/site/index.html\\nprintf ''body{}\\\\n'' > /tmp/lab/.mk/site/style.css\\ntar czf /tmp/lab/site.tar.gz -C /tmp/lab/.mk site\\nrm -rf /tmp/lab/.mk\\nprintf ''a1\\\\n'' > /tmp/lab/data/a.txt\\nprintf ''b1\\\\n'' > /tmp/lab/data/b.txt\\nprintf ''id,qty\\\\n1,10\\\\n2,20\\\\n'' > /tmp/lab/data/report.csv\\nseq 1 200 > /tmp/lab/big.txt\\nprintf ''INFO start\\\\nERROR disk\\\\nINFO ok\\\\nERROR net\\\\nERROR db\\\\n'' | gzip -n > /tmp/lab/server.log.gz\\nprintf ''echo conf\\\\n'' > /tmp/lab/src/conf.sh\\nchmod 750 /tmp/lab/src/conf.sh\\ntouch -d ''2020-01-01 00:00:00'' /tmp/lab/src/conf.sh\\nfor d in 01 02 03 04 05; do : > /tmp/lab/daily/data-2026-01-$d.tar.gz; touch -d \\"2026-01-$d 00:00:00\\" /tmp/lab/daily/data-2026-01-$d.tar.gz; done\\ntrue"]', '["sh", "-c", "( cmp -s /tmp/lab/data/report.csv /tmp/lab/report.bak ) && ( [ \\"$(wc -l < /tmp/lab/sums.txt)\\" -eq 2 ] ) && ( [ \\"$(cut -d\\" \\" -f1 /tmp/lab/sums.txt | sort -u | wc -l)\\" -eq 1 ] && [ \\"$(head -n 1 /tmp/lab/sums.txt | cut -d\\" \\" -f1)\\" = \\"$(sha256sum /tmp/lab/data/report.csv | cut -d\\" \\" -f1)\\" ] ) && ( sha256sum -c /tmp/lab/sums.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "복사본 report.bak 이 있다", "cmd": ["sh", "-c", "cmp -s /tmp/lab/data/report.csv /tmp/lab/report.bak"]}, {"label": "sums.txt 는 두 줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/lab/sums.txt)\\" -eq 2 ]"]}, {"label": "두 해시가 같고 실제 값과 맞다", "cmd": ["sh", "-c", "[ \\"$(cut -d\\" \\" -f1 /tmp/lab/sums.txt | sort -u | wc -l)\\" -eq 1 ] && [ \\"$(head -n 1 /tmp/lab/sums.txt | cut -d\\" \\" -f1)\\" = \\"$(sha256sum /tmp/lab/data/report.csv | cut -d\\" \\" -f1)\\" ]"]}, {"label": "sha256sum -c 가 통과한다", "cmd": ["sh", "-c", "sha256sum -c /tmp/lab/sums.txt"]}]', '[{"title": "GNU tar 매뉴얼", "url": "https://www.gnu.org/software/tar/manual/"}, {"title": "GNU tar 매뉴얼: 파일 제외하기 (--exclude)", "url": "https://www.gnu.org/software/tar/manual/html_section/exclude.html"}, {"title": "GNU coreutils 매뉴얼: cp 사용법 (-a)", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cp-invocation.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 338 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 338, 10, '백업 파일을 안전하게 보관하는 순서', '백업을 만들어 **다른 위치로 옮기고**, 옮긴 파일이 망가지지 않았는지 확인하는 순서입니다. **앞에서 뒤**로 놓으세요.', '원본의 체크섬이 있어야 비교할 수 있고, 비교는 복사가 끝난 뒤에 합니다. 체크섬은 파일을 옮기기 **전에** 기록합니다.', NULL, NULL, '[]', 'order', '["`tar czf` 로 백업 파일을 만든다", "옮기기 전에 `sha256sum` 으로 그 파일의 체크섬을 기록한다", "`cp` 로 백업 파일을 다른 위치에 복사한다", "`sha256sum -c` 로 복사본이 기록해 둔 값과 같은지 확인한다"]', NULL, '**만들기 → 체크섬 기록 → 복사 → 확인** 순서입니다. 파일이 있어야 체크섬을 낼 수 있고, 복사 전의 값이 "정답" 이 되어야 복사본과 비교할 수 있습니다. 확인을 건너뛰면 복사 중에 깨진 백업을 그대로 믿게 됩니다. 복원이 필요한 순간에 알게 되면 이미 늦습니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "GNU tar 매뉴얼", "url": "https://www.gnu.org/software/tar/manual/"}, {"title": "GNU tar 매뉴얼: 파일 제외하기 (--exclude)", "url": "https://www.gnu.org/software/tar/manual/html_section/exclude.html"}, {"title": "GNU coreutils 매뉴얼: cp 사용법 (-a)", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cp-invocation.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 338 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 338, 11, '날짜가 들어간 백업 이름 만들기 ($(date +%F))', '`/tmp/lab/data` 를 **`/tmp/lab/backups/data-날짜.tar.gz`** 로 묶으세요. 날짜는 `date` 명령으로 `YYYY-MM-DD` 모양이 들어가게 합니다 (예: `data-2026-01-31.tar.gz`). 아카이브 안 경로는 `data/...` 로 시작합니다. `backups` 폴더는 이미 있습니다.', '`date +%F` 는 `2026-01-31` 같은 모양으로 날짜를 찍습니다. 명령 결과를 이름 중간에 끼우려면 `$( )` 를 씁니다. 날짜를 손으로 적지 마세요, 내일도 같은 명령이 맞아야 합니다.', 'tar czf /tmp/lab/backups/data-$(date +%F).tar.gz -C /tmp/lab data
ls /tmp/lab/backups

# 매일 같은 명령을 돌려도 이름이 날짜별로 달라서 덮어쓰지 않는다', '["sh", "-c", "rm -rf /tmp/lab /tmp/restore /tmp/*.txt /tmp/*.gz /tmp/*.tgz\\nmkdir -p /tmp/lab/project/bin /tmp/lab/project/logs /tmp/lab/data /tmp/lab/backups /tmp/lab/daily /tmp/lab/src /tmp/lab/.mk/site\\nprintf ''port=8080\\\\nmode=prod\\\\n'' > /tmp/lab/project/app.conf\\nprintf ''remember to rotate\\\\n'' > /tmp/lab/project/notes.txt\\nprintf ''#!/bin/sh\\\\necho run\\\\n'' > /tmp/lab/project/bin/run.sh\\nchmod 755 /tmp/lab/project/bin/run.sh\\nprintf ''start\\\\nwarn\\\\n'' > /tmp/lab/project/logs/app.log\\nprintf ''old line\\\\n'' > /tmp/lab/project/logs/old.log\\nprintf ''hello site\\\\n'' > /tmp/lab/.mk/site/index.html\\nprintf ''body{}\\\\n'' > /tmp/lab/.mk/site/style.css\\ntar czf /tmp/lab/site.tar.gz -C /tmp/lab/.mk site\\nrm -rf /tmp/lab/.mk\\nprintf ''a1\\\\n'' > /tmp/lab/data/a.txt\\nprintf ''b1\\\\n'' > /tmp/lab/data/b.txt\\nprintf ''id,qty\\\\n1,10\\\\n2,20\\\\n'' > /tmp/lab/data/report.csv\\nseq 1 200 > /tmp/lab/big.txt\\nprintf ''INFO start\\\\nERROR disk\\\\nINFO ok\\\\nERROR net\\\\nERROR db\\\\n'' | gzip -n > /tmp/lab/server.log.gz\\nprintf ''echo conf\\\\n'' > /tmp/lab/src/conf.sh\\nchmod 750 /tmp/lab/src/conf.sh\\ntouch -d ''2020-01-01 00:00:00'' /tmp/lab/src/conf.sh\\nfor d in 01 02 03 04 05; do : > /tmp/lab/daily/data-2026-01-$d.tar.gz; touch -d \\"2026-01-$d 00:00:00\\" /tmp/lab/daily/data-2026-01-$d.tar.gz; done\\ntrue"]', '["sh", "-c", "( [ \\"$(ls /tmp/lab/backups | grep -Ec \\"^data-[0-9]{4}-[0-9]{2}-[0-9]{2}\\\\.tar\\\\.gz$\\")\\" -eq 1 ] ) && ( f=$(ls /tmp/lab/backups/data-*.tar.gz | head -n 1); l=$(tar tzf \\"$f\\"); echo \\"$l\\" | grep -qx \\"data/a.txt\\" && echo \\"$l\\" | grep -qx \\"data/report.csv\\" ) && ( f=$(ls /tmp/lab/backups/data-*.tar.gz | head -n 1); ! tar tzf \\"$f\\" | grep -q \\"^tmp/\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "backups 에 data-YYYY-MM-DD.tar.gz 가 한 개 있다", "cmd": ["sh", "-c", "[ \\"$(ls /tmp/lab/backups | grep -Ec \\"^data-[0-9]{4}-[0-9]{2}-[0-9]{2}\\\\.tar\\\\.gz$\\")\\" -eq 1 ]"]}, {"label": "안에 data/a.txt 와 data/report.csv 가 있다", "cmd": ["sh", "-c", "f=$(ls /tmp/lab/backups/data-*.tar.gz | head -n 1); l=$(tar tzf \\"$f\\"); echo \\"$l\\" | grep -qx \\"data/a.txt\\" && echo \\"$l\\" | grep -qx \\"data/report.csv\\""]}, {"label": "앞 경로(tmp/) 가 붙어 있지 않다", "cmd": ["sh", "-c", "f=$(ls /tmp/lab/backups/data-*.tar.gz | head -n 1); ! tar tzf \\"$f\\" | grep -q \\"^tmp/\\""]}]', '[{"title": "GNU tar 매뉴얼", "url": "https://www.gnu.org/software/tar/manual/"}, {"title": "GNU tar 매뉴얼: 파일 제외하기 (--exclude)", "url": "https://www.gnu.org/software/tar/manual/html_section/exclude.html"}, {"title": "GNU coreutils 매뉴얼: cp 사용법 (-a)", "url": "https://www.gnu.org/software/coreutils/manual/html_node/cp-invocation.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 338 AND order_index = 11);

